<script setup>
import { computed, ref,onMounted,nextTick } from 'vue'
import { api, db, devicesView, socketsView } from '../domain/store.js'
import { money } from '../domain/service.js'
import StatusTag from './StatusTag.vue'
import SocketQr from './SocketQr.vue'
import {createDemoState} from '../../../uni-app/src/domain/charging.mjs'
const mobileDemo=createDemoState()
function mobileCode(socket){const site=mobileDemo.stations.find(s=>s.latitude===device.value.station?.lat&&s.longitude===device.value.station?.lng);return site?.devices.find(d=>d.rowName===device.value.row?.name&&d.position===device.value.position)?.sockets[socket.number-1]?.code}
const props=defineProps({id:String,focusSocketId:String}),emit=defineEmits(['order','message'])
const device=computed(()=>devicesView.value.find(d=>d.id===props.id)),sockets=computed(()=>socketsView.value.filter(s=>s.deviceId===props.id)),userId=ref(db.users.find(u=>u.enabled)?.id||''),error=ref('')
function run(action,message){error.value='';try{const result=action();emit('message',message||'模拟状态已更新。');return result}catch(e){error.value=e.message}}
onMounted(()=>nextTick(()=>{if(props.focusSocketId){const node=[...document.querySelectorAll('[data-socket-id]')].find(e=>e.dataset.socketId===props.focusSocketId);node?.scrollIntoView({block:'nearest'})}}))
function start(socket){const order=run(()=>api.requestStartSimulation(socket.id,userId.value),'已提交启动请求，等待模拟设备反馈。');if(order)emit('order',order.id)}
</script>
<template><div class="socket-panel"><div class="device-summary"><div><strong>{{device.code}}</strong><p>{{device.name}} · {{device.station?.name}} · {{device.row?.name}} · 第{{device.position}}台</p></div><StatusTag :text="device.status"/></div><div class="device-summary-counts"><span>通信 <b>{{device.online?'在线':'离线'}}</b></span><span>管理 <b>{{device.enabled?'启用':'停用'}}</b></span><span>插座 <b>{{device.portCount}}</b></span><span>空闲 <b>{{device.free}}</b></span><span>启动中 <b>{{device.starting}}</b></span><span>充电中 <b>{{device.charging}}</b></span><span>异常占用 <b>{{device.abnormal}}</b></span><span>故障 <b>{{device.faults}}</b></span></div><div class="simulation-toolbar"><label>模拟用户<select v-model="userId" aria-label="选择模拟用户"><option v-for="u in db.users" :key="u.id" :value="u.id" :disabled="!u.enabled">{{u.name}}{{u.enabled?'':'（停用）'}}</option></select></label><button class="outline-button" @click="run(()=>api.setDeviceOnline(device.id,!device.online),device.online?'已模拟设备离线，相关充电任务转为异常并保持占用。':'设备已恢复在线；异常任务仍需核验处理。')">{{device.online?'模拟断线':'模拟恢复在线'}}</button></div><p class="form-hint">本页仅用于前端答辩演示。模拟断线或设置故障会将活动任务转异常；恢复在线/故障不会自动结束异常任务。</p><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="socket-grid"><article v-for="socket in sockets" :key="socket.id" :data-socket-id="socket.id" class="socket-card" :class="{'socket-busy':socket.order,'socket-fault':socket.fault,'socket-highlighted':socket.id===focusSocketId}"><div class="socket-card-top"><strong>{{socket.name}}</strong><StatusTag :text="socket.status"/></div><p class="socket-code">{{socket.code}}</p><p v-if="socket.fault" class="socket-warning">{{socket.faultReason}}</p><p v-if="socket.order" class="socket-estimate">{{socket.order.energy.toFixed(3)}} 度 · ¥ {{money(socket.order.total)}} <small>估算</small></p><div class="socket-actions"><button v-if="socket.status==='空闲'" class="soft-button active" @click="start(socket)">模拟启动</button><button v-if="socket.order" class="outline-button" @click="emit('order',socket.order.id)">查看任务</button><button class="table-link" @click="run(()=>api.setSocketEnabled(socket.id,!socket.enabled))">{{socket.enabled?'停用':'启用'}}</button><button class="table-link" @click="run(()=>api.setSocketFault(socket.id,!socket.fault,'人工设置插座故障（软件模拟）'))">{{socket.fault?'核验恢复故障':'模拟故障'}}</button></div><SocketQr v-if="mobileCode(socket)" :code="mobileCode(socket)" :label="'用户端独立演示编号：'+mobileCode(socket)"/><p v-else class="form-hint">此设备不在独立用户端演示目录中；两端统一扫码请使用后端联调模式。</p></article></div></div></template>
